import { describe, it, expect, vi, beforeEach } from 'vitest'
import { setActivePinia, createPinia } from 'pinia'

// Import mocks FIRST
import {
  mockWalletNamed,
  mockHDWalletNamed,
  mockWalletFromId,
  mockMainnetWallet,
  mockChipnetWallet,
  localStorageMock,
  mockGetAllWalletsWithNetworkInfo,
  mockDeleteNamedWallet,
  mockPruneDeletedWalletCaches,
  mockClearWalletSettings,
  mockGetNamedWalletId,
  mockCashconnectStart,
  mockWizardconnectStart,
} from './mocks/store.mocks'

const mockRemoveEmptyChipnetCopy = vi.hoisted(() => vi.fn())
vi.mock('src/utils/wallet/tiedWallets', () => ({
  removeEmptyChipnetCopy: mockRemoveEmptyChipnetCopy,
}))

// Import store after mocks
import { useStore } from '../src/stores/store'

describe('switchWallet', () => {
  beforeEach(() => {
    vi.clearAllMocks()
    localStorageMock.clear()
    // Create fresh Pinia instance for each test
    setActivePinia(createPinia())
  })

  describe('wallet loading', () => {
    it('loads mainnet wallet when network is mainnet', async () => {
      localStorageMock.setItem('network', 'mainnet')

      const store = useStore()
      // Set initial wallet to avoid "No wallet set" error
      await store.setWallet(mockMainnetWallet as never)

      await store.switchWallet('newWallet')

      expect(mockGetNamedWalletId).toHaveBeenCalledWith('newWallet', 'bitcoincash')
      expect(mockWalletFromId).toHaveBeenCalledWith('seed:mainnet:test mnemonic:m/44\'/145\'/0\'/0/0', { network: 'mainnet' })
      expect(mockWalletNamed).not.toHaveBeenCalled()
      expect(mockHDWalletNamed).not.toHaveBeenCalled()
    })

    it('loads chipnet wallet when network is chipnet', async () => {
      localStorageMock.setItem('network', 'chipnet')

      const store = useStore()
      await store.setWallet(mockChipnetWallet as never)

      await store.switchWallet('newWallet')

      expect(mockGetNamedWalletId).toHaveBeenCalledWith('newWallet', 'bchtest')
      expect(mockWalletFromId).toHaveBeenCalledWith('seed:testnet:test mnemonic:m/44\'/145\'/0\'/0/0', { network: 'testnet' })
      expect(mockHDWalletNamed).not.toHaveBeenCalled()
      expect(mockWalletNamed).not.toHaveBeenCalled()
    })

    it('defaults to mainnet when no network in localStorage', async () => {
      // No network set in localStorage

      const store = useStore()
      await store.setWallet(mockMainnetWallet as never)

      await store.switchWallet('newWallet')

      expect(mockWalletFromId).toHaveBeenCalledWith('seed:mainnet:test mnemonic:m/44\'/145\'/0\'/0/0', { network: 'mainnet' })
      expect(mockWalletNamed).not.toHaveBeenCalled()
    })
  })

  describe('state updates', () => {
    beforeEach(() => {
      localStorageMock.setItem('network', 'mainnet')
    })

    it('updates activeWalletName in store', async () => {
      const store = useStore()
      await store.setWallet(mockMainnetWallet as never)

      await store.switchWallet('differentWallet')

      expect(store.activeWalletName).toBe('differentWallet')
    })

    it('persists activeWalletName to localStorage', async () => {
      const store = useStore()
      await store.setWallet(mockMainnetWallet as never)

      await store.switchWallet('persistedWallet')

      expect(localStorageMock.setItem).toHaveBeenCalledWith('activeWalletName', 'persistedWallet')
    })

    it('sets _wallet to mainnet wallet instance', async () => {
      const store = useStore()
      await store.setWallet(mockMainnetWallet as never)

      await store.switchWallet('newWallet')

      // Verify wallet was set by checking its properties
      expect(store._wallet?.network).toBe('mainnet')
      expect(store._wallet?.getDepositAddress()).toBe(mockMainnetWallet.cashaddr)
    })

    it('sets _wallet to chipnet wallet instance', async () => {
      localStorageMock.setItem('network', 'chipnet')
      const store = useStore()
      await store.setWallet(mockMainnetWallet as never)

      await store.switchWallet('newWallet')

      // Verify chipnet wallet was set by checking its properties
      expect(store._wallet?.network).toBe('testnet')
      expect(store._wallet?.getDepositAddress()).toBe(mockChipnetWallet.cashaddr)
    })
  })

  describe('network fallback for network-specific wallets', () => {
    it('switches to mainnet when wallet only exists on mainnet and current network is chipnet', async () => {
      localStorageMock.setItem('network', 'chipnet')
      const store = useStore()
      await store.setWallet(mockChipnetWallet as never)
      // Set up availableWallets with a mainnet-only wallet
      store.availableWallets = [
        { name: 'mainnetOnlyWallet', networks: ['mainnet'] }
      ]

      const result = await store.switchWallet('mainnetOnlyWallet')

      expect(result.success).toBe(true)
      expect(result.networkChanged).toBe('mainnet')
      expect(store.activeWalletName).toBe('mainnetOnlyWallet')
      expect(localStorageMock.setItem).toHaveBeenCalledWith('activeWalletName', 'mainnetOnlyWallet')
      // Should NOT have loaded a wallet by name (we're switching away from chipnet)
      expect(mockHDWalletNamed).not.toHaveBeenCalled()
      // Verify network was changed and correct wallet loader was called
      expect(localStorageMock.setItem).toHaveBeenCalledWith('network', 'mainnet')
      expect(mockWalletFromId).toHaveBeenCalledWith('seed:mainnet:test mnemonic:m/44\'/145\'/0\'/0/0', { network: 'mainnet' })
      expect(mockWalletNamed).not.toHaveBeenCalled()
    })

    it('switches to chipnet when wallet only exists on chipnet and current network is mainnet', async () => {
      localStorageMock.setItem('network', 'mainnet')
      const store = useStore()
      await store.setWallet(mockMainnetWallet as never)
      // Set up availableWallets with a chipnet-only wallet
      store.availableWallets = [
        { name: 'chipnetOnlyWallet', networks: ['chipnet'] }
      ]

      const result = await store.switchWallet('chipnetOnlyWallet')

      expect(result.success).toBe(true)
      expect(result.networkChanged).toBe('chipnet')
      expect(store.activeWalletName).toBe('chipnetOnlyWallet')
      expect(localStorageMock.setItem).toHaveBeenCalledWith('activeWalletName', 'chipnetOnlyWallet')
      // Should NOT have called Wallet.named (we're switching away from mainnet)
      expect(mockWalletNamed).not.toHaveBeenCalled()
      // Verify network was changed and correct wallet loader was called
      expect(localStorageMock.setItem).toHaveBeenCalledWith('network', 'chipnet')
      expect(mockWalletFromId).toHaveBeenCalledWith('seed:testnet:test mnemonic:m/44\'/145\'/0\'/0/0', { network: 'testnet' })
      expect(mockHDWalletNamed).not.toHaveBeenCalled()
    })

    it('opens a wallet with a mainnet row on mainnet, even when the stored network is chipnet', async () => {
      localStorageMock.setItem('network', 'chipnet')
      const store = useStore()
      await store.setWallet(mockChipnetWallet as never)
      // an older wallet with its chipnet copy, listed under the mainnet wallets
      store.availableWallets = [
        { name: 'bothNetworks', networks: ['mainnet', 'chipnet'] }
      ]

      const result = await store.switchWallet('bothNetworks')

      expect(result.networkChanged).toBe('mainnet')
      expect(mockGetNamedWalletId).toHaveBeenCalledWith('bothNetworks', 'bitcoincash')
      expect(mockWalletFromId).not.toHaveBeenCalledWith(expect.anything(), { network: 'testnet' })
      expect(localStorageMock.setItem).toHaveBeenCalledWith('network', 'mainnet')
    })

    it('does not change network when wallet exists on current network', async () => {
      localStorageMock.setItem('network', 'mainnet')
      const store = useStore()
      await store.setWallet(mockMainnetWallet as never)
      // Wallet exists on both networks
      store.availableWallets = [
        { name: 'bothNetworks', networks: ['mainnet', 'chipnet'] }
      ]

      const result = await store.switchWallet('bothNetworks')

      expect(result.success).toBe(true)
      expect(result.networkChanged).toBeUndefined()
      expect(mockWalletFromId).toHaveBeenCalledWith('seed:mainnet:test mnemonic:m/44\'/145\'/0\'/0/0', { network: 'mainnet' })
      expect(mockWalletNamed).not.toHaveBeenCalled()
    })

    it('loads wallet normally when not in availableWallets but present in IndexedDB', async () => {
      localStorageMock.setItem('network', 'mainnet')
      const store = useStore()
      await store.setWallet(mockMainnetWallet as never)
      store.availableWallets = [] // Empty list

      const result = await store.switchWallet('unknownWallet')

      expect(result.success).toBe(true)
      expect(result.networkChanged).toBeUndefined()
      expect(mockGetNamedWalletId).toHaveBeenCalledWith('unknownWallet', 'bitcoincash')
      expect(mockWalletFromId).toHaveBeenCalledWith('seed:mainnet:test mnemonic:m/44\'/145\'/0\'/0/0', { network: 'mainnet' })
      expect(mockWalletNamed).not.toHaveBeenCalled()
    })
  })

  describe('error handling', () => {
    it('throws without calling .named() when wallet does not exist in IndexedDB', async () => {
      localStorageMock.setItem('network', 'mainnet')
      mockGetNamedWalletId.mockResolvedValueOnce(undefined)

      const store = useStore()
      await store.setWallet(mockMainnetWallet as never)

      await expect(store.switchWallet('ghostWallet')).rejects.toThrowError()
      // .named() would silently create a new wallet with a fresh seed
      expect(mockWalletNamed).not.toHaveBeenCalled()
      expect(mockHDWalletNamed).not.toHaveBeenCalled()
    })

    it('does not mutate state when a stale availableWallets entry points to a missing wallet', async () => {
      localStorageMock.setItem('network', 'mainnet')
      localStorageMock.setItem.mockClear()
      mockGetNamedWalletId.mockResolvedValueOnce(undefined)

      const store = useStore()
      await store.setWallet(mockMainnetWallet as never)
      store.activeWalletName = 'originalWallet'
      // Stale list claims the wallet exists on chipnet, but IndexedDB disagrees
      store.availableWallets = [
        { name: 'staleWallet', networks: ['chipnet'] }
      ]

      await expect(store.switchWallet('staleWallet')).rejects.toThrowError()

      expect(mockHDWalletNamed).not.toHaveBeenCalled()
      expect(store.activeWalletName).toBe('originalWallet')
      expect(localStorageMock.setItem).not.toHaveBeenCalledWith('activeWalletName', 'staleWallet')
      expect(localStorageMock.setItem).not.toHaveBeenCalledWith('network', 'chipnet')
    })

    it('throws when wallet loading fails', async () => {
      localStorageMock.setItem('network', 'mainnet')
      mockWalletFromId.mockRejectedValueOnce(new Error('Wallet not found'))

      const store = useStore()
      await store.setWallet(mockMainnetWallet as never)

      await expect(store.switchWallet('nonexistentWallet')).rejects.toThrowError()
    })

    it('does not mutate state when wallet loading fails', async () => {
      localStorageMock.setItem('network', 'mainnet')
      localStorageMock.setItem('activeWalletName', 'originalWallet')
      localStorageMock.setItem.mockClear()
      mockWalletFromId.mockRejectedValueOnce(new Error('Wallet not found'))

      const store = useStore()
      await store.setWallet(mockMainnetWallet as never)
      store.activeWalletName = 'originalWallet'
      store.displayView = 5
      const originalWalletRef = store._wallet

      try {
        await store.switchWallet('failedWallet')
      } catch {
        // Expected to throw
      }

      // No state should be mutated on failure
      expect(store.activeWalletName).toBe('originalWallet')
      expect(store._wallet).toBe(originalWalletRef)
      expect(store.displayView).toBe(5)
      expect(localStorageMock.setItem).not.toHaveBeenCalledWith('activeWalletName', 'failedWallet')
    })
  })
})

describe('changeNetwork', () => {
  beforeEach(() => {
    vi.clearAllMocks()
    localStorageMock.clear()
    setActivePinia(createPinia())
  })

  it('loads the wallet on the new network when it exists there', async () => {
    localStorageMock.setItem('network', 'mainnet')

    const store = useStore()
    await store.setWallet(mockMainnetWallet as never)
    store.activeWalletName = 'myWallet'

    expect(await store.changeNetwork('chipnet')).toBe(true)

    expect(mockGetNamedWalletId).toHaveBeenCalledWith('myWallet', 'bchtest')
    expect(mockWalletFromId).toHaveBeenCalledWith('seed:testnet:test mnemonic:m/44\'/145\'/0\'/0/0', { network: 'testnet' })
    expect(mockHDWalletNamed).not.toHaveBeenCalled()
    expect(localStorageMock.setItem).toHaveBeenCalledWith('network', 'chipnet')
  })

  it('does not create a new wallet when it does not exist on the target network', async () => {
    localStorageMock.setItem('network', 'mainnet')
    mockGetNamedWalletId.mockResolvedValueOnce(undefined)

    const store = useStore()
    await store.setWallet(mockMainnetWallet as never)
    store.activeWalletName = 'myWallet'
    const originalWalletRef = store._wallet

    expect(await store.changeNetwork('chipnet')).toBe(false)

    // .named() would silently create a new wallet with a fresh seed
    expect(mockHDWalletNamed).not.toHaveBeenCalled()
    expect(mockWalletNamed).not.toHaveBeenCalled()
    // current wallet state and configured network are left untouched
    expect(store._wallet).toBe(originalWalletRef)
    expect(store.activeWalletName).toBe('myWallet')
    expect(localStorageMock.setItem).not.toHaveBeenCalledWith('network', 'chipnet')
  })
})

describe('deleteWallet', () => {
  beforeEach(() => {
    vi.clearAllMocks()
    localStorageMock.clear()
    setActivePinia(createPinia())
    mockGetAllWalletsWithNetworkInfo.mockResolvedValue([])
  })

  it('throws when trying to delete the active wallet', async () => {
    const store = useStore()
    await store.setWallet(mockMainnetWallet as never)
    // activeWalletName defaults to 'mywallet'

    await expect(store.deleteWallet('mywallet')).rejects.toThrowError()
  })

  it('does not call deleteNamedWallet when trying to delete active wallet', async () => {
    const store = useStore()
    await store.setWallet(mockMainnetWallet as never)

    try {
      await store.deleteWallet('mywallet')
    } catch {
      // Expected to throw
    }

    expect(mockDeleteNamedWallet).not.toHaveBeenCalled()
  })

  it('deletes the wallet from every network database', async () => {
    const store = useStore()
    await store.setWallet(mockMainnetWallet as never)

    await store.deleteWallet('otherWallet')

    expect(mockDeleteNamedWallet.mock.calls).toEqual([
      ['otherWallet', 'bitcoincash'],
      ['otherWallet', 'bchtest'],
      ['otherWallet', 'bchtest4'],
    ])
  })

  // The seed is deleted above, but the library caches a private key per address for HD wallets
  // in a database of its own, which would still be able to spend from the deleted wallet
  it('prunes the HD wallet key cache so no spendable keys outlive the wallet', async () => {
    const store = useStore()
    await store.setWallet(mockMainnetWallet as never)

    await store.deleteWallet('otherWallet')

    expect(mockPruneDeletedWalletCaches).toHaveBeenCalled()
  })

  it('clears the settings of the deleted wallet', async () => {
    const store = useStore()
    await store.setWallet(mockMainnetWallet as never)

    await store.deleteWallet('otherWallet')

    expect(mockClearWalletSettings).toHaveBeenCalledWith('otherWallet')
  })

  // The wallet is already gone when the prune runs, so its failure is reported on its own rather
  // than making the deletion look like it failed and stranding the per-wallet cleanup with it
  it('still succeeds and cleans up when the key cache prune fails', async () => {
    const store = useStore()
    await store.setWallet(mockMainnetWallet as never)
    mockPruneDeletedWalletCaches.mockRejectedValueOnce(new Error('prune failed'))

    await expect(store.deleteWallet('otherWallet')).resolves.toBeUndefined()

    expect(mockClearWalletSettings).toHaveBeenCalledWith('otherWallet')
    expect(mockDeleteNamedWallet).toHaveBeenCalledWith('otherWallet', 'bitcoincash')
  })

  it('does not prune the key cache when the delete is refused', async () => {
    const store = useStore()
    await store.setWallet(mockMainnetWallet as never)

    try {
      await store.deleteWallet('mywallet')
    } catch {
      // Expected to throw, deleting the active wallet is refused
    }

    expect(mockPruneDeletedWalletCaches).not.toHaveBeenCalled()
  })

  it('refreshes available wallets after deletion', async () => {
    const store = useStore()
    await store.setWallet(mockMainnetWallet as never)

    await store.deleteWallet('otherWallet')

    expect(mockGetAllWalletsWithNetworkInfo).toHaveBeenCalled()
  })

  it('propagates error if mainnet deletion fails (testnet not attempted)', async () => {
    mockDeleteNamedWallet.mockRejectedValueOnce(new Error('DB error'))
    const store = useStore()
    await store.setWallet(mockMainnetWallet as never)

    await expect(store.deleteWallet('otherWallet')).rejects.toThrowError()

    // Only mainnet deletion was attempted before failure
    expect(mockDeleteNamedWallet).toHaveBeenCalledTimes(1)
    expect(mockDeleteNamedWallet).toHaveBeenCalledWith('otherWallet', 'bitcoincash')
    // Wallet list not refreshed on failure
    expect(mockGetAllWalletsWithNetworkInfo).not.toHaveBeenCalled()
  })

  it('propagates error if testnet deletion fails (mainnet already deleted)', async () => {
    mockDeleteNamedWallet
      .mockResolvedValueOnce(undefined) // mainnet succeeds
      .mockRejectedValueOnce(new Error('DB error')) // testnet fails
    const store = useStore()
    await store.setWallet(mockMainnetWallet as never)

    await expect(store.deleteWallet('otherWallet')).rejects.toThrowError()

    // Both deletions were attempted
    expect(mockDeleteNamedWallet).toHaveBeenCalledTimes(2)
    // Wallet list not refreshed on failure
    expect(mockGetAllWalletsWithNetworkInfo).not.toHaveBeenCalled()
  })
})

describe('removeChipnetCopy', () => {
  beforeEach(() => {
    vi.clearAllMocks()
    localStorageMock.clear()
    setActivePinia(createPinia())
    mockRemoveEmptyChipnetCopy.mockResolvedValue(undefined)
  })

  it('removes the copy of a wallet open on mainnet without switching', async () => {
    const store = useStore()
    await store.setWallet(mockMainnetWallet as never)
    store.activeWalletName = 'myWallet'
    vi.clearAllMocks()

    expect(await store.removeChipnetCopy('myWallet', 'checked-id')).toBe(true)

    expect(mockRemoveEmptyChipnetCopy).toHaveBeenCalledWith('myWallet', 'checked-id')
    expect(mockGetNamedWalletId).not.toHaveBeenCalled()
    expect(store.network).toBe('mainnet')
  })

  it('leaves the chipnet copy in use for mainnet first, and removes nothing when that fails', async () => {
    const store = useStore()
    await store.setWallet(mockChipnetWallet as never)
    store.activeWalletName = 'myWallet'

    mockGetNamedWalletId.mockResolvedValueOnce(undefined)
    expect(await store.removeChipnetCopy('myWallet', 'checked-id')).toBe(false)
    expect(mockRemoveEmptyChipnetCopy).not.toHaveBeenCalled()

    expect(await store.removeChipnetCopy('myWallet', 'checked-id')).toBe(true)
    expect(mockWalletFromId).toHaveBeenCalled()
    expect(store.network).toBe('mainnet')
    expect(mockRemoveEmptyChipnetCopy).toHaveBeenCalledWith('myWallet', 'checked-id')
  })

  it('opens no wallet on another network while the removal runs', async () => {
    let finishRemoval = () => {}
    mockRemoveEmptyChipnetCopy.mockImplementation(() => new Promise<void>(resolve => { finishRemoval = resolve }))
    const store = useStore()
    await store.setWallet(mockMainnetWallet as never)
    store.activeWalletName = 'myWallet'

    const removal = store.removeChipnetCopy('myWallet', 'checked-id')
    await vi.waitFor(() => expect(mockRemoveEmptyChipnetCopy).toHaveBeenCalled())
    expect(store.removingChipnetCopy).toBe(true)

    expect(await store.changeNetwork('chipnet')).toBe(false)
    expect(mockWalletFromId).not.toHaveBeenCalledWith(expect.anything(), { network: 'testnet' })
    expect(store.network).toBe('mainnet')

    finishRemoval()
    expect(await removal).toBe(true)
    expect(store.removingChipnetCopy).toBe(false)
  })

  it('holds the guard from the first step, while the open copy is left for mainnet', async () => {
    let finishLoad = () => {}
    const store = useStore()
    await store.setWallet(mockChipnetWallet as never)
    store.activeWalletName = 'myWallet'
    // the mainnet row of the copy being left loads slowly
    mockGetNamedWalletId.mockImplementationOnce(() => new Promise(resolve => {
      finishLoad = () => resolve('seed:mainnet:test mnemonic:m/44\'/145\'/0\'/0/0')
    }))

    const removal = store.removeChipnetCopy('myWallet', 'checked-id')
    expect(store.removingChipnetCopy).toBe(true)
    // neither opening the copy again nor a second removal gets in meanwhile
    expect(await store.changeNetwork('chipnet')).toBe(false)
    expect(await store.removeChipnetCopy('myWallet', 'checked-id')).toBe(false)

    finishLoad()
    expect(await removal).toBe(true)
    expect(mockRemoveEmptyChipnetCopy).toHaveBeenCalledTimes(1)
    expect(store.network).toBe('mainnet')
    expect(store.removingChipnetCopy).toBe(false)
  })
})

// A test network a dApp cannot tell from chipnet: no CashConnect or WizardConnect starts on it,
// which would bring back the sessions the same seed paired on another network
describe('a testnet4 wallet', () => {
  beforeEach(() => {
    vi.clearAllMocks()
    localStorageMock.clear()
    setActivePinia(createPinia())
  })

  it('loads from the testnet4 database, on testnet4', async () => {
    mockGetAllWalletsWithNetworkInfo.mockResolvedValue([{ name: 'dev', networks: ['testnet4'] }])
    const store = useStore()
    await store.setWallet(mockMainnetWallet as never)
    store.availableWallets = [{ name: 'dev', networks: ['testnet4'] }]

    const result = await store.switchWallet('dev')

    expect(result.networkChanged).toBe('testnet4')
    expect(mockGetNamedWalletId).toHaveBeenCalledWith('dev', 'bchtest4')
    expect(mockWalletFromId).toHaveBeenCalledWith('seed:testnet4:test mnemonic:m/44\'/145\'/0\'/0/0', { network: 'testnet4' })
  })

  it('starts no CashConnect or WizardConnect, where a chipnet wallet does', async () => {
    const store = useStore()
    await store.setWallet({ ...mockChipnetWallet, network: 'testnet4' } as never)
    await store.initializeWallet()
    expect(mockCashconnectStart).not.toHaveBeenCalled()
    expect(mockWizardconnectStart).not.toHaveBeenCalled()

    await store.setWallet(mockChipnetWallet as never)
    await store.initializeWallet()
    expect(mockCashconnectStart).toHaveBeenCalled()
  })
})
